#include <bits/stdc++.h>
struct T {
    int v;
    T(int x) : v(x) { std::cout << "ctor " << v << "\n"; }
    T(const T& o) : v(o.v) { std::cout << "copy ctor " << v << "\n"; }
    T& operator=(const T& o) { v = o.v; std::cout << "copy assign " << v << "\n"; return *this; }
};
void byValue(T t) { std::cout << "in byValue " << t.v << "\n"; }
int main() {
    T a(1);
    T b = a;      // declared on this line -> copy constructor
    T c(2);
    c = a;        // c already exists -> copy assignment
    byValue(a);   // parameter is created from a -> copy constructor
    T d = T(5);   // C++17: guaranteed elision, no copy at all
    std::cout << "done " << b.v << c.v << d.v << "\n";
}

#include <bits/stdc++.h>
// Shallow copy aliases the buffer; deep copy owns its own.
struct Shallow {
    int* p;
    Shallow(int v) : p(new int(v)) {}
};  // default copy copies the pointer value only
struct Deep {
    int* p;
    Deep(int v) : p(new int(v)) {}
    Deep(const Deep& o) : p(new int(*o.p)) {}  // new block, copy contents
    ~Deep() { delete p; }
};
int main() {
    Shallow s1(10);
    Shallow s2 = s1;
    *s2.p = 99;
    std::cout << "shallow: s1=" << *s1.p << " s2=" << *s2.p
              << " same address? " << (s1.p == s2.p) << "\n";
    delete s1.p;  // only once: deleting both would be a double free
    Deep d1(10);
    Deep d2 = d1;
    *d2.p = 99;
    std::cout << "deep: d1=" << *d1.p << " d2=" << *d2.p
              << " same address? " << (d1.p == d2.p) << "\n";
}

#include <bits/stdc++.h>
// Rule of Zero: no special members, members manage themselves.
struct Zero {
    std::string name;
    std::vector<int> data;
};
// Rule of Five: declares a destructor, so we declare all five.
struct Five {
    int* p;
    Five(int v) : p(new int(v)) {}
    ~Five() { delete p; }
    Five(const Five& o) : p(new int(*o.p)) { std::cout << "copy\n"; }
    Five& operator=(const Five& o) {
        if (this != &o) { int* n = new int(*o.p); delete p; p = n; }
        std::cout << "copy assign\n"; return *this;
    }
    Five(Five&& o) noexcept : p(o.p) { o.p = nullptr; std::cout << "move\n"; }
    Five& operator=(Five&& o) noexcept {
        std::swap(p, o.p); std::cout << "move assign\n"; return *this;
    }
};
// Declares only a destructor: implicit moves are suppressed, so "moves" copy.
struct OnlyDtor {
    std::vector<int> v;
    ~OnlyDtor() {}
};
int main() {
    Zero z{"a", {1, 2}};
    Zero z2 = std::move(z);
    std::cout << "zero moved, source data size = " << z.data.size() << "\n";
    Five f(1);
    Five g = std::move(f);
    Five h = f.p ? f : g;  // f was moved from, so this copies g
    OnlyDtor o{{1, 2, 3}};
    OnlyDtor o2 = std::move(o);
    std::cout << "OnlyDtor source size after 'move' = " << o.v.size() << "\n";
    std::cout << "z2 " << z2.data.size() << " h " << *h.p << "\n";
}

#include <bits/stdc++.h>
struct Noisy {
    std::string s;
    Noisy(std::string x) : s(std::move(x)) {}
    Noisy(const Noisy& o) : s(o.s) { std::cout << "  copy\n"; }
    Noisy(Noisy&& o) noexcept : s(std::move(o.s)) { std::cout << "  move\n"; }
};
int main() {
    Noisy a("hello world, long enough to be on the heap");
    std::cout << "std::move(a) only casts; nothing printed yet\n";
    auto&& r = std::move(a);          // still the same object
    std::cout << "size after cast: " << a.s.size() << "\n";
    std::cout << "construct from std::move(a):\n";
    Noisy b(std::move(a));            // move ctor chosen here
    std::cout << "a.s size now: " << a.s.size() << " (valid but unspecified)\n";
    a.s = "reuse";                    // assigning to moved-from is fine
    std::cout << "a reused: " << a.s << "\n";
    const Noisy c("const object");
    std::cout << "move from const:\n";
    Noisy d(std::move(c));            // const T&& binds to copy ctor
    (void)r; (void)b; (void)d;
}

#include <bits/stdc++.h>
static int copies = 0, moves = 0;
struct Safe {
    std::string s = "x";
    Safe() = default;
    Safe(const Safe&) { ++copies; }
    Safe(Safe&&) noexcept { ++moves; }
};
struct Risky {
    std::string s = "x";
    Risky() = default;
    Risky(const Risky&) { ++copies; }
    Risky(Risky&&) { ++moves; }  // not noexcept
};
template <class T>
void grow(const char* name) {
    copies = moves = 0;
    std::vector<T> v;
    v.reserve(4);
    for (int i = 0; i < 4; ++i) v.emplace_back();
    copies = moves = 0;
    v.emplace_back();            // exceeds capacity 4, forces reallocation
    std::cout << name << ": nothrow move = "
              << std::is_nothrow_move_constructible_v<T>
              << ", copies=" << copies << " moves=" << moves << "\n";
}
int main() {
    grow<Safe>("Safe ");
    grow<Risky>("Risky");
}

#include <bits/stdc++.h>
// A hand-made vtable: array of function pointers per "class".
struct Obj;
using Fn = void (*)(Obj*);
struct VTable { Fn speak; };
struct Obj { const VTable* vptr; int id; };
void animalSpeak(Obj* o) { std::cout << "animal " << o->id << " makes a sound\n"; }
void dogSpeak(Obj* o) { std::cout << "dog " << o->id << " says woof\n"; }
const VTable animalVT{animalSpeak};  // one table per class
const VTable dogVT{dogSpeak};
struct A { virtual void f() {} int x; };
struct B { int x; };
int main() {
    Obj a{&animalVT, 1}, d{&dogVT, 2};
    Obj* ps[] = {&a, &d};
    for (Obj* p : ps) p->vptr->speak(p);  // load vptr, load slot, indirect call
    std::cout << "sizeof(with virtual) = " << sizeof(A)
              << ", sizeof(without) = " << sizeof(B) << "\n";
    A obj; A* base = &obj;
    std::cout << "real virtual call works: ";
    struct D : A { void f() override { std::cout << "D::f\n"; } } dd;
    base = &dd; base->f();
}

#include <bits/stdc++.h>
struct Base {
    virtual void f(int) { std::cout << "Base::f(int)\n"; }
    virtual void f(double) { std::cout << "Base::f(double)\n"; }
    virtual void g() const { std::cout << "Base::g\n"; }
    void h(int) { std::cout << "Base::h(int)\n"; }
    virtual ~Base() = default;
};
struct Derived : Base {
    void f(int) override { std::cout << "Derived::f(int)\n"; }  // overrides
    // void g() override {}  // would not compile: missing const
    void h(const char*) { std::cout << "Derived::h(const char*)\n"; }  // hides Base::h
    using Base::f;  // brings f(double) back into scope
};
void over(int) { std::cout << "over(int)\n"; }       // overloading: compile time
void over(double) { std::cout << "over(double)\n"; }
int main() {
    Derived d; Base& b = d;
    b.f(1);        // dispatches at runtime -> Derived::f(int)
    b.f(1.5);      // Base::f(double)
    d.f(1.5);      // visible only thanks to using
    d.h("x");
    // d.h(1);     // error: Derived::h hides Base::h(int)
    d.Base::h(1);
    over(1); over(1.5);
}

#include <bits/stdc++.h>
class Shape {
    std::string name;
public:
    explicit Shape(std::string n) : name(std::move(n)) {}   // ctor allowed
    virtual double area() const = 0;                        // pure virtual
    virtual void describe() const = 0;
    virtual ~Shape() = default;
    const std::string& getName() const { return name; }
};
void Shape::describe() const {                              // pure virtual with body
    std::cout << getName() << " area=" << area() << "\n";
}
struct Square : Shape {
    double s;
    Square(double x) : Shape("square"), s(x) {}
    double area() const override { return s * s; }
    void describe() const override {
        std::cout << "[Square] ";
        Shape::describe();                                  // explicit base call
    }
};
int main() {
    // Shape x("a");  // error: abstract
    std::vector<std::unique_ptr<Shape>> v;
    v.push_back(std::make_unique<Square>(3));
    for (auto& s : v) s->describe();
    std::cout << "is_abstract<Shape>=" << std::is_abstract_v<Shape> << "\n";
}

#include <bits/stdc++.h>
struct BadBase { ~BadBase() { std::cout << "~BadBase\n"; } };
struct BadDerived : BadBase { ~BadDerived() { std::cout << "~BadDerived\n"; } };
struct Base { virtual ~Base() { std::cout << "~Base\n"; } };
struct Derived : Base {
    std::string big = "member";
    ~Derived() override { std::cout << "~Derived\n"; }
};
int main() {
    std::cout << "virtual destructor:\n";
    Base* p = new Derived;
    delete p;  // runs ~Derived then ~Base
    std::cout << "non-virtual (formally undefined behaviour; static type used):\n";
    // We call through the static type explicitly to show what the compiler does.
    BadDerived* d = new BadDerived;
    BadBase* q = d;
    q->~BadBase();               // only ~BadBase runs, ~BadDerived is skipped
    ::operator delete(d);        // free the raw memory without running ~BadDerived
    std::cout << "sizeof(BadBase)=" << sizeof(BadBase)
              << " sizeof(Base)=" << sizeof(Base) << "\n";
}

#include <bits/stdc++.h>
struct Member {
    const char* n;
    Member(const char* x) : n(x) { std::cout << "  member " << n << " ctor\n"; }
    ~Member() { std::cout << "  member " << n << " dtor\n"; }
};
struct Base {
    Member bm{"base"};
    Base() { std::cout << "  Base ctor, who() = "; who(); }
    virtual void who() { std::cout << "Base\n"; }
    virtual ~Base() { std::cout << "  Base dtor, who() = "; who(); }
};
struct Derived : Base {
    Member m2{"second"}, m1{"first"};  // order follows declaration, not the init list
    Derived() : m1("first"), m2("second") { std::cout << "  Derived ctor body\n"; }
    void who() override { std::cout << "Derived\n"; }
    ~Derived() override { std::cout << "  Derived dtor body\n"; }
};
int main() {
    std::cout << "construct:\n";
    {
        Derived d;
        std::cout << "after construction, who() = "; d.who();
        std::cout << "destroy:\n";
    }
}

#include <bits/stdc++.h>
struct Animal {
    virtual std::string speak() const { return "..."; }
    virtual ~Animal() = default;
};
struct Dog : Animal {
    std::string tag = "rex";
    std::string speak() const override { return "woof " + tag; }
};
std::string byValue(Animal a) { return a.speak(); }       // slices
std::string byRef(const Animal& a) { return a.speak(); }  // keeps dynamic type
int main() {
    Dog d;
    std::cout << "by reference: " << byRef(d) << "\n";
    std::cout << "by value:     " << byValue(d) << "\n";   // base version runs
    std::vector<Animal> bad;
    bad.push_back(d);                                        // sliced copy stored
    std::cout << "vector<Animal>: " << bad[0].speak() << "\n";
    std::vector<std::unique_ptr<Animal>> good;
    good.push_back(std::make_unique<Dog>());
    std::cout << "vector<unique_ptr>: " << good[0]->speak() << "\n";
    std::cout << "sizeof(Animal)=" << sizeof(Animal)
              << " sizeof(Dog)=" << sizeof(Dog) << "\n";
}

#include <bits/stdc++.h>
class Vec {
    double x, y;
public:
    Vec(double a = 0, double b = 0) : x(a), y(b) {}
    Vec& operator+=(const Vec& o) { x += o.x; y += o.y; return *this; }  // member
    friend Vec operator+(Vec a, const Vec& b) { return a += b; }          // hidden friend
    friend Vec operator*(double k, const Vec& v) { return Vec(k * v.x, k * v.y); }
    Vec& operator++() { ++x; ++y; return *this; }                         // prefix
    Vec operator++(int) { Vec old = *this; ++*this; return old; }         // postfix
    friend std::ostream& operator<<(std::ostream& o, const Vec& v) {
        return o << "(" << v.x << ", " << v.y << ")";
    }
    bool operator==(const Vec&) const = default;
};
int main() {
    Vec a(1, 2), b(3, 4);
    std::cout << "a+b = " << a + b << "\n";
    std::cout << "2*a = " << 2 * a << "\n";   // works because it is a non-member
    Vec c = a++;
    std::cout << "post: c=" << c << " a=" << a << "\n";
    std::cout << "pre: " << ++a << "\n";
    std::cout << "equal? " << (Vec(1, 2) == Vec(1, 2)) << "\n";
}

#include <bits/stdc++.h>
struct Point {
    int x, y;
    auto operator<=>(const Point&) const = default;  // also declares ==
};
struct Name {
    std::string s;
    std::weak_ordering operator<=>(const Name& o) const {   // hand-written
        auto lower = [](std::string t) {
            for (auto& c : t) c = std::tolower(static_cast<unsigned char>(c));
            return t;
        };
        return lower(s) <=> lower(o.s);
    }
    bool operator==(const Name& o) const { return (*this <=> o) == 0; }
};
struct D { double v; auto operator<=>(const D&) const = default; };
int main() {
    Point a{1, 5}, b{2, 0};
    std::cout << "(1,5) < (2,0): " << (a < b) << ", == : " << (a == b) << "\n";
    Name n1{"Alice"}, n2{"ALICE"};
    std::cout << "Alice == ALICE (case-insens): " << (n1 == n2) << "\n";
    D nan{std::nan("")}, one{1.0};
    auto r = nan <=> one;
    std::cout << "NaN <=> 1 unordered? " << (r == std::partial_ordering::unordered) << "\n";
    std::cout << "NaN < 1: " << (nan < one) << "\n";
    std::cout << "category of Point: "
              << std::is_same_v<decltype(a <=> b), std::strong_ordering> << "\n";
}

#include <bits/stdc++.h>
class Buf {
    int* d; size_t n;
public:
    Buf(size_t k, int v) : d(new int[k]), n(k) { std::fill(d, d + k, v); }
    Buf(const Buf& o) : d(new int[o.n]), n(o.n) { std::copy(o.d, o.d + n, d); }
    ~Buf() { delete[] d; }
    // Option 1: allocate-then-release (strong guarantee, self-assign safe)
    Buf& assign1(const Buf& o) {
        int* nd = new int[o.n];            // may throw: *this untouched
        std::copy(o.d, o.d + o.n, nd);
        delete[] d; d = nd; n = o.n;
        return *this;
    }
    // Option 2: copy-and-swap (copy happens in the parameter)
    friend void swap(Buf& a, Buf& b) noexcept { std::swap(a.d, b.d); std::swap(a.n, b.n); }
    Buf& operator=(Buf other) noexcept { swap(*this, other); return *this; }
    void show(const char* t) const {
        std::cout << t << ":"; for (size_t i = 0; i < n; ++i) std::cout << ' ' << d[i];
        std::cout << "\n";
    }
};
int main() {
    Buf a(3, 1), b(2, 7), c(4, 5);
    a.assign1(b); a.show("assign1 a=b");
    a.assign1(a); a.show("assign1 self");
    c = a;        c.show("copy-swap c=a");
    c = c;        c.show("copy-swap self");
}

#include <bits/stdc++.h>
struct Shape {
    virtual std::unique_ptr<Shape> clone() const = 0;   // virtual copy
    virtual std::string name() const = 0;
    virtual ~Shape() = default;
};
template <class D>
struct Cloneable : Shape {                               // CRTP helper
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<D>(static_cast<const D&>(*this));
    }
};
struct Circle : Cloneable<Circle> {
    int r = 3;
    std::string name() const override { return "circle r=" + std::to_string(r); }
};
struct Square : Cloneable<Square> {
    int s = 4;
    std::string name() const override { return "square s=" + std::to_string(s); }
};
// Closed set of types: std::variant copies by value with no heap.
using V = std::variant<Circle, Square>;
int main() {
    std::unique_ptr<Shape> a = std::make_unique<Circle>();
    const Shape& ref = *a;                  // only a Base reference
    auto b = ref.clone();                   // dynamic type preserved
    dynamic_cast<Circle&>(*a).r = 10;
    std::cout << "original: " << a->name() << "\n";
    std::cout << "clone:    " << b->name() << "\n";
    V v1 = Square{}, v2 = v1;               // variant copy
    std::get<Square>(v2).s = 9;
    std::cout << "variant: " << std::get<Square>(v1).s << " vs " << std::get<Square>(v2).s << "\n";
}
